script.setup:
// image-q reduces the picture to a small palette (Wu, NeuQuant or RgbQuant) and redraws it with only
// those colors, dithered (Floyd–Steinberg, Atkinson, ...). Left of the divider: the original;
// right: the quantized image. The strip at the bottom is the palette.
const iq = await ctx.utils.import("https://esm.sh/image-q@4.0.0");
const bitmap = await createImageBitmap(await (await fetch(ctx.assets["great-wave.jpg"])).blob());
const W = 320, H = Math.round((W * bitmap.height) / bitmap.width);
const canvas = new OffscreenCanvas(W, H), c2 = canvas.getContext("2d", { willReadFrequently: true });
c2.drawImage(bitmap, 0, 0, W, H);
const pixels = c2.getImageData(0, 0, W, H).data;
const gl = ctx.gl;
const makeTex = (data) => {
  const t = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, t);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, W, H, 0, gl.RGBA, gl.UNSIGNED_BYTE, data);
  for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.NEAREST], [gl.TEXTURE_MAG_FILTER, gl.NEAREST], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
  return t;
};
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_src; uniform sampler2D u_dst; uniform vec2 u_fit; uniform float u_split;
uniform vec3 u_pal[64]; uniform int u_count;
void main() {
  vec3 bg = vec3(0.07, 0.07, 0.08);
  float strip = 0.07;
  if (v_uv.y < strip) {
    vec3 c = bg;
    if (u_count > 0 && v_uv.y > 0.015 && v_uv.y < strip - 0.015) {
      float x = (v_uv.x - 0.04) / 0.92;
      int i = int(floor(x * float(u_count)));
      if (x >= 0.0 && x < 1.0) c = u_pal[i];
    }
    outColor = vec4(c, 1.0); return;
  }
  vec2 q = vec2(v_uv.x, (v_uv.y - strip) / (1.0 - strip));
  q = (q - 0.5) / u_fit + 0.5;
  vec3 c = bg;
  if (all(greaterThanEqual(q, vec2(0.0))) && all(lessThanEqual(q, vec2(1.0)))) {
    vec2 t = vec2(q.x, 1.0 - q.y);
    c = q.x < u_split ? texture(u_src, t).rgb : texture(u_dst, t).rgb;
    c = mix(c, vec3(1.0), (1.0 - smoothstep(0.001, 0.003, abs(q.x - u_split))) * 0.9);
  }
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, { iq, W, H, pixels, src: makeTex(pixels), dst: makeTex(pixels), key: "", changed: 0, busy: false, ready: null,
  pal: new Float32Array(64 * 3), count: 0, moved: false,
  PALETTES: ["wuquant", "neuquant", "rgbquant"],
  DITHERS: ["nearest", "floyd-steinberg", "atkinson", "stucki", "sierra-lite", "riemersma"],
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const colors = Math.max(2, Math.min(64, u.u_colors | 0));
const key = [colors, u.u_palette, u.u_dither].join("|");
if (key !== s.key) { s.key = key; s.changed = ctx.time; s.pending = true; }
// Quantize off the render path (image-q's async API yields between steps), once the controls settle.
if (s.pending && !s.busy && ctx.time - s.changed > 0.12) {
  s.pending = false; s.busy = true;
  const opts = { colorDistanceFormula: "euclidean-bt709-noalpha" };
  const image = s.iq.utils.PointContainer.fromUint8Array(s.pixels, s.W, s.H);
  const t0 = performance.now();
  s.iq.buildPalette([image], { ...opts, paletteQuantization: s.PALETTES[u.u_palette] ?? "wuquant", colors })
    .then((palette) => s.iq.applyPalette(image, palette, { ...opts, imageQuantization: s.DITHERS[u.u_dither] ?? "nearest" })
      .then((out) => { s.ready = { data: out.toUint8Array(), points: palette.getPointContainer().getPointArray(), ms: performance.now() - t0 }; }))
    .catch((e) => console.error(e))
    .finally(() => { s.busy = false; });
}
if (s.ready) {
  const { data, points, ms } = s.ready; s.ready = null;
  gl.bindTexture(gl.TEXTURE_2D, s.dst);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, s.W, s.H, gl.RGBA, gl.UNSIGNED_BYTE, data);
  // sort the palette by luminance for a tidy strip
  points.sort((a, b) => (0.2126 * a.r + 0.7152 * a.g + 0.0722 * a.b) - (0.2126 * b.r + 0.7152 * b.g + 0.0722 * b.b));
  s.pal.fill(0); points.slice(0, 64).forEach((p, i) => s.pal.set([p.r / 255, p.g / 255, p.b / 255], i * 3));
  s.count = Math.min(64, points.length);
  ctx.publish("palette colors", s.count);
  ctx.publish("quantize ms", Math.round(ms));
}
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const img = s.W / s.H, view = w / (h * 0.93);
const fit = img > view ? [0.94, 0.94 * view / img] : [0.94 * img / view, 0.94];
const mx = ((ctx.mouse[0] - 0.5) / fit[0]) + 0.5;
const split = s.moved ? mx : 0.3 + 0.2 * Math.sin(ctx.time * 0.4);
gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_src", s.src, 0);
ctx.utils.bindTexture(s.p, "u_dst", s.dst, 1);
ctx.utils.drawFullscreen(s.p, { u_fit: fit, u_split: split, u_pal: s.pal, u_count: s.count });
